INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(108516, 'ruRU', '', 'Мне будет забавно смотреть, как ты плавишься!', 24330),
(108517, 'ruRU', '', 'Кому нужны прислужники? Я сожгу тебя сама!', 24330),
(108518, 'ruRU', '', 'Полагаю, мой брат Мардранел готов сопровождать тебя. Спасибо за помощь, друг.', 24330),
(108550, 'ruRU', '', 'Наши усилия не были напрасны. Матриарх Лунного Шёпота наблюдает издалека.', 24330),
(108551, 'ruRU', '', 'Пусть твоя охота всегда будет плодотворной, сестра моя.', 24330),
(108555, 'ruRU', '', 'Никто не противостоит Кошмару!', 24330),
(108557, 'ruRU', '', 'Отдайся ему, как сделала я.', 24330),
(108558, 'ruRU', '', 'Наконец-то... приходит долгий сон.', 24330),
(108562, 'ruRU', '', 'От Кошмара не скрыться.', 24330),
(108566, 'ruRU', '', 'Духи леса! Стражи природы! Услышьте нашу мольбу!', 24330),
(108567, 'ruRU', '', 'В этот день Мать-Древо возродилось! Джаханир снова цел!', 24330),
(108580, 'ruRU', '', 'Похоже, этот фонарь был слегка модифицирован. Должно быть, именно его нужно использовать, чтобы подать сигнал.', 24330),
(108581, 'ruRU', '', 'Подай сигнал Ли''лет Лунное Пламя.', 24330),
(108582, 'ruRU', '', 'Твоё появление весьма кстати. Сегодня вечером знать собралась в честь Великого Магистра.', 24330),
(108583, 'ruRU', '', 'Наши шпионы докладывают, что сама Элизанда будет присутствовать. Это редкая возможность застать её вдали от источника силы.', 24330),
(108584, 'ruRU', '', 'Мы воспользуемся боковым входом на территорию... слишком много глаз следит за фасадом.', 24330),
(108585, 'ruRU', '', 'Пока у тебя неплохо получалось, но нам нужно убедиться, что ты сольёшься с толпой на приёме. Я улучшу твою маскировку, напитав её скрытой магией, чтобы ты выглядел как один из аристократов.', 24330),
(108586, 'ruRU', '', 'Это твой лучший шанс устранить Великого Магистра. Удачи!', 24330),
(108587, 'ruRU', '', 'Убейте их, глупцы! Мне не откажут в моей судьбе!', 24330),
(108592, 'ruRU', '', 'Я не скажу тебе НИЧЕГО!', 24330),
(108604, 'ruRU', '', 'Да, в чём дело? Я очень занята, планирую свой следующий бал.', 24330),
(108605, 'ruRU', '', 'Ох, снова ты! Не могу отблагодарить тебя в достаточной мере за то, что ты сделал, дорогой.$b$bЯ уже слышу хорошие отзывы о новом ювелире. Пожалуй, мне стоит его навестить и заказать новое украшение...', 24330),
(108616, 'ruRU', '', 'Нуждаешься в лечении?', 24330),
(108618, 'ruRU', '', 'Ну да, есть. Немного на том сундуке вон там. Но у нас их мало, так что, пожалуйста, не бери слишком много.', 24330),
(108620, 'ruRU', '', 'Лей-ткачиха из Сурамара проходила здесь не так давно. Думаю, она направилась на восток, к Лесным Водопадам.', 24330),
(108623, 'ruRU', '', 'Найди безопасное место! Я найду тебя, когда всё закончится.', 24330),
(108631, 'ruRU', '', 'Ты смеешь просить меня о такой чёрной работе? Ты, должно быть, шутишь.$b$bНе шутишь? Понятно. Что ж, я уже некоторое время вдали от Сурамара, и, судя по твоему виду, ты алхимик, да?$b$bЯ был бы готов обменять свои услуги на цену, которую сочту справедливой.$b$bЯ тоскую по Напитку Снов Изеры. Это древний эльфийский напиток. Чтобы его приготовить, тебе понадобится сонный лист, а также листья Слезы Сновидца.$b$bОдин такой растёт неподалёку отсюда, на поляне среди каких-то руин. Возьми мою флягу, приготовь этот напиток для меня, и я сделаю то, о чём ты просишь.', 24330),
(108632, 'ruRU', '', 'Ты меня не интересуешь. Я происхожу из прославленного рода портных Сурамара. Ты, очевидно, нет.', 24330),
(108634, 'ruRU', '', 'Здравствуй, лей-ткач. Чем могу помочь?', 24330),
(108635, 'ruRU', '', 'Какая удача! Собрат-портной!$b$bДобро пожаловать в гильдию лей-ткачей Сурамара. Возможно, ты о нас слышал?', 24330),
(108636, 'ruRU', '', 'Ты принёс мне мои настойки?', 24330),
(108639, 'ruRU', '', 'Да, этого будет достаточно. Теперь дай взглянуть на твой шёлк.', 24330),
(108643, 'ruRU', '', 'Вот, держи. А теперь беги по своим делам.', 24330),
(108663, 'ruRU', '', 'Я, разумеется, предвидела твоё появление. Нити судьбы, что привели тебя сюда. Твою отчаянную попытку остановить Легион.', 24330),
(108664, 'ruRU', '', 'Мой народ столкнулся с похожей дилеммой. Я вглядывалась во все возможные будущие в поисках ответа... и нашла лишь один.', 24330),
(108665, 'ruRU', '', 'Победа Легиона неизбежна. Каждый поток времени это подтверждает. Если бы мы сопротивлялись, они захватили бы Ночной Колодец силой и оставили бы нас без него.', 24330),
(108666, 'ruRU', '', 'Я не могла позволить своему народу голодать, угасать без его энергии, что нас поддерживает. Поэтому была заключена сделка.', 24330),
(108667, 'ruRU', '', 'Теперь я вижу будущее, где Легион побеждает, а мой народ выживает. Это та нить, которую нужно сохранить. Я сделаю всё в моих силах, чтобы так оно и было!', 24330),
(108668, 'ruRU', '', 'Ваши смерти обеспечивают будущее Ночнорождённых. Что ж, подойдите. Позвольте ускорить вашу встречу с судьбой.', 24330),
(108669, 'ruRU', '', 'Ваши временные линии заканчиваются здесь!', 24330);
